/* STG2C green-room (real Mednafen .mc3 save-state BAT/VRAM/CRAM)
 *
 * Generated by tools/pack_state_window.py:
 *   stage2c_green_state_maps.bin : 1 screen x 32x24 BAT entries
 *   stage2c_green_state_tiles.bin: 50 distinct 8x8 tiles converted to MD format
 *   stage2c_green_state_pal.bin  : 4 MD palettes (exact-color packed)
 *   player_spr.bin         : engine player test art
 */

.section .rodata
#include <macros.s>

GLABEL res_stage2c_green_state_tiles
.incbin "../res/gfx/stage2c_green_state_tiles.bin"
.align 2

GLABEL res_stage2c_green_state_pal
.byte 0
.byte 63
.incbin "../res/gfx/stage2c_green_state_pal.bin"
.align 2

GLABEL res_stage2c_green_state_maps
.incbin "../res/gfx/stage2c_green_state_maps.bin"
.align 2

GLABEL res_player_spr
.incbin "../res/gfx/player_spr.bin"
.align 2
